import{_ as e,o as r,c as o,ag as a}from"./chunks/framework.B3IQijK_.js";const h=JSON.parse('{"title":"Concepts and terminology","description":"Understand the durable objects, lifecycle stages, operating principles, and shared language of Trading Office.","frontmatter":{"title":"Concepts and terminology","description":"Understand the durable objects, lifecycle stages, operating principles, and shared language of Trading Office.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/concepts"}]]},"headers":[],"relativePath":"trading-office/concepts.md","filePath":"trading-office/concepts.md"}'),n={name:"trading-office/concepts.md"};function s(i,t,d,l,c,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="concepts-and-terminology" tabindex="-1">Concepts and terminology <a class="header-anchor" href="#concepts-and-terminology" aria-label="Permalink to &quot;Concepts and terminology&quot;">​</a></h1><p>Trading Office connects conversations to durable work. These terms describe the objects that survive a session and keep research, strategy operation, and review consistent.</p><h2 id="the-main-objects" tabindex="-1">The main objects <a class="header-anchor" href="#the-main-objects" aria-label="Permalink to &quot;The main objects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Trading book</strong></td><td>The boundary for one market&#39;s paper cash, positions, ledger, team, research, and workflows; currently labeled <strong>fund book</strong> in the interface</td></tr><tr><td><strong>AI employee</strong></td><td>A role-bound agent with its own identity, mandate, tools, book scope, and responsibility for attributed work</td></tr><tr><td><strong>Office lead</strong></td><td>The selected book&#39;s coordination surface for setup, delegation, and controls; currently labeled the <strong>CEO pane</strong></td></tr><tr><td><strong>Employee pane</strong></td><td>A working surface with its own employee identity and book scope</td></tr><tr><td><strong>Trading Office records</strong></td><td>The local records behind the workspace: books, employees, research, workflows, transactions, strategies, journals, and reviews</td></tr><tr><td><strong>Mandate</strong></td><td>Stored permissions, limits, scope, cadence, and escalation rules for an employee</td></tr><tr><td><strong>Office workflow</strong></td><td>A reusable employee-owned responsibility with persisted scheduled runs</td></tr><tr><td><strong>Market watchlist</strong></td><td>A saved group of symbols for browsing; it does not schedule AI work</td></tr><tr><td><strong>Watch</strong></td><td>A scheduled AI observation that gathers fresh context and reports material changes</td></tr><tr><td><strong>Workflow heartbeat</strong></td><td>Background transport that advances due Office work and unfinished backtest chunks</td></tr><tr><td><strong>Position monitor</strong></td><td>Deterministic checking of recorded paper stops, targets, and time exits</td></tr><tr><td><strong>Strategy Lab</strong></td><td>The idea-to-verdict testing workflow; the current <code>/backtest</code> menu is labeled <strong>Backtest Lab</strong></td></tr></tbody></table><h2 id="strategy-lifecycle-terms" tabindex="-1">Strategy lifecycle terms <a class="header-anchor" href="#strategy-lifecycle-terms" aria-label="Permalink to &quot;Strategy lifecycle terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Idea</strong></td><td>An observation or suspected relationship preserved before it becomes a formal strategy</td></tr><tr><td><strong>Hypothesis</strong></td><td>A falsifiable trading claim with an entry, exit, scope, and result that would count against it</td></tr><tr><td><strong>Experiment plan</strong></td><td>The immutable symbols, dates, parameters, costs, validation, and ranking rule approved before a backtest</td></tr><tr><td><strong>Experiment job</strong></td><td>The persisted, chunked execution of an approved plan</td></tr><tr><td><strong>Machine verdict</strong></td><td>The system-owned promising, rejected, or inconclusive result from JUDGE</td></tr><tr><td><strong>Strategy version</strong></td><td>A frozen promoted implementation, parameter set, exits, universe, fingerprint, and evidence link</td></tr><tr><td><strong>Paper deployment</strong></td><td>Recorded authorization to use one strategy version for paper trading within defined risk limits</td></tr><tr><td><strong>Journal</strong></td><td>Version-tagged paper activity and its computed outcomes</td></tr><tr><td><strong>Forward check</strong></td><td>A test of the unchanged version over history that arrived after promotion</td></tr><tr><td><strong>Review</strong></td><td>A human Keep, Pause, Retire, or Improve decision that preserves the earlier evidence</td></tr><tr><td><strong>Child hypothesis</strong></td><td>One explicit proposed change linked to its reviewed parent strategy</td></tr></tbody></table><h2 id="the-evidence-lifecycle" tabindex="-1">The evidence lifecycle <a class="header-anchor" href="#the-evidence-lifecycle" aria-label="Permalink to &quot;The evidence lifecycle&quot;">​</a></h2><p>Strategy Lab follows a fixed contract:</p><table tabindex="0"><thead><tr><th>Stage</th><th>What becomes durable</th></tr></thead><tbody><tr><td><strong>BUILD</strong></td><td>The compiled strategy implementation and its fingerprint</td></tr><tr><td><strong>PLAN</strong></td><td>The exact experiment specification and approval</td></tr><tr><td><strong>RUN</strong></td><td>Completed chunks, cells, progress, and results</td></tr><tr><td><strong>JUDGE</strong></td><td>One promising, rejected, or inconclusive verdict</td></tr><tr><td><strong>PROMOTE</strong></td><td>A frozen strategy version, lineage, evidence links, and paper deployment</td></tr></tbody></table><p>The broader Trading Office journey continues beyond the experiment:</p><p><strong>Idea → research → test → judge → promote → paper trade → monitor → review → improve</strong></p><h2 id="operating-principles" tabindex="-1">Operating principles <a class="header-anchor" href="#operating-principles" aria-label="Permalink to &quot;Operating principles&quot;">​</a></h2><ol><li><strong>Everything belongs to a book.</strong> Research, workflows, strategies, and paper activity stay inside the selected trading context.</li><li><strong>Durable state outranks chat.</strong> Jobs, verdicts, approvals, transactions, journals, and reviews are the source of truth.</li><li><strong>AI proposes and interprets; systems own facts.</strong> Prices, risk math, progress, verdicts, approvals, and fills come from the tools that produce them.</li><li><strong>Mandates constrain employee action.</strong> Scope, risk limits, required stops, escalation rules, and kill switches apply to scheduled and interactive work.</li><li><strong>An approved experiment is immutable.</strong> Changing the test creates a new plan and approval point.</li><li><strong>Promotion requires evidence.</strong> A strategy version inherits the implementation, parameters, lineage, and result that earned promotion.</li><li><strong>Paper trading stays traceable.</strong> Trades carry their strategy-version and deployment identities into the ledger and journal.</li><li><strong>Improvement preserves history.</strong> A proposed change creates a child hypothesis rather than rewriting the reviewed parent.</li><li><strong>Automation tools have distinct jobs.</strong> Watches observe, workflows assign responsibility, heartbeat resumes work, and position monitoring applies recorded exits.</li><li><strong>Paper and live activity remain distinct.</strong> An Office paper transaction is not a broker order.</li></ol><h2 id="how-the-systems-fit-together" tabindex="-1">How the systems fit together <a class="header-anchor" href="#how-the-systems-fit-together" aria-label="Permalink to &quot;How the systems fit together&quot;">​</a></h2><ul><li><strong>tradecli</strong> is the product: conversation, roles, delegation, charts, market tools, automation, and paper-trade surfaces.</li><li><strong>Trading Office</strong> is the workspace in tradecli that connects the full strategy loop and its local records.</li><li><strong>Connected systems</strong> provide external truth and capabilities, including model providers, TradingView, market-data services, and configured brokers.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/trading-sandbox-website-preview/wiki/trading-office/">Trading Office overview</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/quickstart">Your first strategy</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/watches">Automation tools</a></li><li><a href="/trading-sandbox-website-preview/wiki/trading-office/commands">Commands and shortcuts</a></li></ul>',17)])])}const m=e(n,[["render",s]]);export{h as __pageData,m as default};
